// shaders lindos ♥ https://www.shadertoy.com/playlist/cXBGzV
#define rot(a) mat2(cos(a + vec4(0, 11, 33, 0)))
#define t (iTime * .8)
#define FAR 20.
#define PI acos(-1.)
#define TAU (2.*PI)

float h21(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 43.123);
    return fract((p3.x + p3.y) * p3.z);
}

float smax(float a, float b) {
    float k = .04;
    float f = max(0., 1. - abs(b - a) / k);
    return max(a, b) + k * .25 * f * f;
}

float porca(vec3 p, float f){
    float d, k = 10.;
    vec3 q = pow(abs(p), vec3(k));
    d = pow(q.x + q.y + q.z, 1. / k) - f;
    d = smax(d, length(p) - f * 1.45);
    d = smax(d, .2 - length(p.xy));
    return d;
}


float map(vec3 p){
    p.xy = vec2(
             atan(p.y, p.x) * 1.292,
             log(length(p.xy)) * 1.4
         ) * 1.6;

    p.x += cos(iTime * .16);
    p.y += sin(iTime * .1);

    vec3 q = vec3(fract(p.xy) - .5, p.z - .5);
    vec3 k;

    k.z = tanh(cos(
              dot(cos(floor(p.xy ) * .8), 2. * vec2(cos(t * .4), sin(t * .3)))
              + t * 3.
          ) * 8.) * .4 - .22;

    return smax(-p.z + .35, -porca(q - k, .47));//
}

float march(vec3 ro, vec3 rd) {
    float d, s, i;

    while(i++ < 64.) {
        s = map(ro + d * rd);
        if(abs(s) < .01 || d > FAR) break;
        d += i < 32. ? s * .4 : s * .9;
    }

    return min(d, FAR);
}


vec3 normal(vec3 p) {
    vec3 e = vec3(.001, 0, 0);
    vec3 v = vec3(
                 map(p - e.xyy),
                 map(p - e.yxy),
                 map(p - e.yyx)
             ) - map(p);
    return normalize(-v);
}

float AO(vec3 p, vec3 n) {
    float sca = 2., occ;

    for(int i; i < 6; i ++) {
        float hr = float(i + 1) * .15 / 3.;
        float d = map(p + n * hr);
        occ +=(hr - d) * sca;
        sca *= .7;
    }
    return clamp(1. - occ, 0., 1.);
}

void mainImage(out vec4 o, vec2 u) {
    vec2 r = iResolution.xy;
    u = (u - r / 2.) / r.y;
    o *= 0.;

    vec3 ro = vec3(0, 0, -5),
         D = normalize(
                 vec3(u, 2.5)
             );





    float d = march(ro, D);

    if(d < FAR) {
        vec3 p = ro + d * D,
             N = normal(p),
             ref = reflect(D, N);

        float diff = length(sin(ref * 6.) * .5 + .5);
        float spec = pow(diff * .4, 5.) * 5.;
        vec4 alb = vec4(.7);
        o = (alb * diff * .6 + spec) * AO(p, ref * 2.);
        o = pow(o, vec4(.8));
    }
}
